package cn.pawday.payment;

import cn.pawday.common.Api.Failure;
import cn.pawday.common.IdempotentCommandExecutor;
import cn.pawday.identity.*;
import cn.pawday.audit.AuditWriter;
import cn.pawday.outbox.OutboxWriter;
import cn.pawday.pilot.PilotPolicy;
import cn.pawday.publishing.PublishingSupport;
import static cn.pawday.publishing.PublishingSupport.*;
import jakarta.servlet.http.HttpServletRequest;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.core.env.Environment;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

/** Synthetic service finance. No goods inventory, coupons, points, membership or disbursement. */
@Service
public class ServiceTradeFinance {
 private final PublishingSupport p;private final TransactionTemplate tx;private final IdempotentCommandExecutor commands;
 private final ObjectProvider<PaymentGateway> gateways;private final AuditWriter audit;private final OutboxWriter outbox;
 private final AccessGuard guard;private final AuthService auth;private final Clock clock;private final PilotPolicy pilot;
 private final boolean enabled,paymentEnabled,recoveryEnabled;private final long leaseMs;
 private static final String ACTIVE="('CREATED','CHANNEL_PENDING','UNKNOWN')";
 private static final String DUE="state IN ('RESERVED','PROCESSING','UNKNOWN','FAILED_RETRYABLE') AND next_retry_at<=clock_timestamp() AND (lease_until IS NULL OR lease_until<=clock_timestamp())";
 public ServiceTradeFinance(PublishingSupport p,TransactionTemplate tx,IdempotentCommandExecutor commands,ObjectProvider<PaymentGateway> gateways,AuditWriter audit,OutboxWriter outbox,AccessGuard guard,AuthService auth,Clock clock,PilotPolicy pilot,Environment env){
  this.p=p;this.tx=tx;this.commands=commands;this.gateways=gateways;this.audit=audit;this.outbox=outbox;this.guard=guard;this.auth=auth;this.clock=clock;this.pilot=pilot;
  enabled=env.getProperty("pawday.service-trade.simulation-enabled",Boolean.class,false)&&env.getProperty("pawday.booking.simulation-enabled",Boolean.class,false)
   &&Set.of("development","test","pilot").contains(env.getProperty("pawday.deployment-mode","development"))&&Arrays.stream(env.getActiveProfiles()).noneMatch(Set.of("prod","production")::contains);
  paymentEnabled=env.getProperty("pawday.payment.simulation-enabled",Boolean.class,false);recoveryEnabled=env.getProperty("pawday.service-trade.finance-recovery-enabled",Boolean.class,true);
  leaseMs=Math.max(1,env.getProperty("pawday.refund.lease-ms",Long.class,60000L));
 }
 public void gate(){if(!enabled)throw new Failure(404,"SERVICE_TRADE_SIMULATION_DISABLED");if(pilot.paused())throw new Failure(503,"PILOT_PAUSED");}
 public void channelGate(){gate();if(!paymentEnabled)throw new Failure(404,"SERVICE_PAYMENT_SIMULATION_DISABLED");if(!(gateways.getIfAvailable() instanceof SimulatedPaymentGateway))throw new Failure(503,"SERVICE_SIMULATED_PROVIDER_REQUIRED");}
 private PaymentGateway gateway(){channelGate();return gateways.getIfAvailable();}
 private Timestamp now(){return Timestamp.from(clock.instant());}
 private Map<String,Object> payment(UUID trade){return p.one("SELECT * FROM payments WHERE service_trade_id=?",trade);}
 private Map<String,Object> owned(Actor a,UUID id){gate();if(a.realm()!=Actor.Realm.CONSUMER)throw new Failure(403,"PERMISSION_DENIED");return p.one("SELECT * FROM service_trade_orders WHERE id=? AND user_id=?",id,a.userId());}
 private void staff(Actor a,UUID store){gate();permission(a,Actor.Realm.MERCHANT,"service.trade.cancel");guard.store(a,store);p.one("SELECT s.id FROM merchant_store s JOIN merchant m ON m.id=s.merchant_id WHERE s.id=? AND m.id=? AND m.status='ACTIVE'",store,a.merchantId());}
 public Map<String,Object> lockTrade(UUID id,boolean write){gate();var seed=p.one("SELECT slot_id FROM service_trade_orders WHERE id=?",id);String clause=write?" FOR UPDATE":" FOR SHARE";p.one("SELECT id FROM booking_slots WHERE id=?"+clause,seed.get("slot_id"));return p.one("SELECT * FROM service_trade_orders WHERE id=?"+clause,id);}
 public void createIntent(UUID id){p.db.update("INSERT INTO payments(id,payment_no,service_trade_id,amount_fen,currency,status,expires_at,created_at) SELECT ?,'SP'||replace(id::text,'-',''),id,payable_fen,'CNY',CASE WHEN order_state='AWAITING_PAYMENT' THEN 'PENDING' ELSE 'CLOSED' END,hold_expires_at,created_at FROM service_trade_orders WHERE id=? ON CONFLICT(service_trade_id) DO NOTHING",UUID.randomUUID(),id);}
 private void record(Actor a,String action,UUID id,Map<String,Object> detail,HttpServletRequest request){audit.write(a,action,"SERVICE_TRADE",id.toString(),Map.of(),detail,request);}
 private void bump(UUID id){p.db.update("UPDATE service_trade_orders SET version=version+1 WHERE id=?",id);}
 private boolean unknown(UUID pid){return p.db.queryForObject("SELECT EXISTS(SELECT 1 FROM payment_attempts WHERE payment_id=? AND status='UNKNOWN')",Boolean.class,pid);}
 private String paymentState(Map<String,Object> payment){return "PROCESSING".equals(payment.get("status"))&&unknown((UUID)payment.get("id"))?"UNKNOWN":payment.get("status").toString();}
 public Map<String,Object> tradeView(UUID id){return tx.execute(s->{var row=lockTrade(id,false);var pay=p.one("SELECT * FROM payments WHERE service_trade_id=? FOR SHARE",id);var slot=p.one("SELECT starts_at FROM booking_slots WHERE id=?",row.get("slot_id"));var v=new LinkedHashMap<String,Object>();
  for(String key:List.of("id","store_id","service_id","slot_id","terms_id","terms_sha256","payable_fen","order_state","capacity_state","version","hold_expires_at","receipt_id","confirmed_at"))v.put(key,row.get(key));
  long paid="SUCCEEDED".equals(pay.get("status"))?number(pay.get("amount_fen")):0;
  long refunded=sum(id,"state='SUCCEEDED'"),reserved=sum(id,"state<>'SUCCEEDED'");
  v.put("currency","CNY");v.put("payment_state",paymentState(pay));v.put("starts_at",slot.get("starts_at"));v.put("paid_fen",paid);v.put("refunded_fen",refunded);v.put("refund_reserved_fen",reserved);
  for(String key:List.of("commission_fen","commission_reversed_fen","merchant_net_fen"))v.put(key,paid==0?0:null);
  v.put("fulfillment_state",row.get("fulfillment_state"));v.put("settlement_state",p.db.queryForObject("SELECT service_trade_settlement_state(?,?)",String.class,id,now()));v.put("settlement_buffer_ends_at",null);v.put("as_of",clock.instant().toString());v.put("open_dispute",p.db.queryForObject("SELECT service_trade_open_dispute(?)",Boolean.class,id));v.put("unresolved_collection_case",p.db.queryForObject("SELECT EXISTS(SELECT 1 FROM payment_cases WHERE payment_id=? AND status<>'REFUNDED')",Boolean.class,pay.get("id")));v.put("simulated",true);return p.view(v);
 });}
 /** Internal amounts are returned only through explicitly authorized staff routes. */
 public Map<String,Object> staffTradeView(UUID trade){return tx.execute(s->{
  var result=tradeView(trade);var rows=p.db.queryForList("SELECT a.commission_fen,(SELECT coalesce(sum(amount_fen),0) FROM service_trade_ledger_entries WHERE trade_id=a.trade_id AND entry_type='SERVICE_COMMISSION_REVERSAL') AS reversed_fen FROM service_trade_allocations a WHERE a.trade_id=?",trade);
  if(!rows.isEmpty()){var allocation=rows.getFirst();long commission=number(allocation.get("commission_fen")),reversed=number(allocation.get("reversed_fen"));result.put("commission_fen",commission);result.put("commission_reversed_fen",reversed);result.put("merchant_net_fen",number(result.get("paid_fen"))-number(result.get("refunded_fen"))-commission+reversed);}
  return result;
 });}
 private long sum(UUID trade,String predicate){return p.db.queryForObject("SELECT coalesce(sum(amount_fen),0) FROM service_trade_refunds WHERE trade_id=? AND source_kind<>'COMPENSATION' AND "+predicate,Long.class,trade);}
 private Map<String,Object> payView(UUID trade){return tx.execute(s->{lockTrade(trade,false);var pay=p.one("SELECT * FROM payments WHERE service_trade_id=? FOR SHARE",trade);var attempts=p.db.queryForList("SELECT id FROM payment_attempts WHERE payment_id=? ORDER BY created_at DESC,id DESC LIMIT 1",pay.get("id"));var v=new LinkedHashMap<String,Object>();v.put("id",pay.get("id"));v.put("trade_id",trade);v.put("state",paymentState(pay));v.put("attempt_id",attempts.isEmpty()?null:attempts.getFirst().get("id"));v.put("receipt_id",pay.get("successful_receipt_id"));v.put("collected_fen","SUCCEEDED".equals(pay.get("status"))?pay.get("amount_fen"):0);v.put("currency","CNY");v.put("version",pay.get("version"));v.put("simulated",true);return v;});}
 public Map<String,Object> readPayment(Actor a,UUID trade){owned(a,trade);channelGate();return payView(trade);}
 public Map<String,Object> attempt(Actor a,UUID trade,Map<String,Object>b,String match,String key,HttpServletRequest r){owned(a,trade);channelGate();fields(b,"channel","client_platform");if(!"SIMULATED_TEST".equals(b.get("channel"))||!("ANDROID".equals(b.get("client_platform"))||"WEB".equals(b.get("client_platform"))))throw new Failure(400,"VALIDATION_ERROR");long version=version(match);
  var command=commands.command(a,"service.trade.payment.attempt:"+trade,key,Map.of("body",b,"version",version),()->{channelGate();var row=lockTrade(trade,true);sameVersion(row,version);var pay=p.one("SELECT * FROM payments WHERE service_trade_id=? FOR UPDATE",trade);
   if(!"AWAITING_PAYMENT".equals(row.get("order_state"))||!"HELD".equals(row.get("capacity_state"))||!"PENDING".equals(pay.get("status")))throw new Failure(409,"PAYMENT_NOT_PAYABLE");
   if(!((Timestamp)pay.get("expires_at")).toInstant().isAfter(clock.instant()))throw new Failure(409,"PAYMENT_WINDOW_EXPIRED");
   p.one("SELECT s.id FROM booking_services s JOIN nearby_store_profile n ON n.store_id=s.store_id JOIN merchant_store st ON st.id=s.store_id JOIN merchant m ON m.id=st.merchant_id WHERE s.id=? AND s.status='ACTIVE' AND m.status='ACTIVE' AND n.publication_status='PUBLISHED' AND n.claim_status='VERIFIED'",row.get("service_id"));
   if(p.db.queryForObject("SELECT count(*) FROM payment_attempts WHERE payment_id=? AND status IN "+ACTIVE,Integer.class,pay.get("id"))>0)throw new Failure(409,"PAYMENT_CONFIRMATION_PENDING");
   UUID attempt=UUID.randomUUID();p.db.update("INSERT INTO payment_attempts(id,payment_id,attempt_no,channel,client_platform) VALUES (?,?,?,'SIMULATED_TEST',?)",attempt,pay.get("id"),"SA"+attempt.toString().replace("-",""),b.get("client_platform"));p.db.update("INSERT INTO payment_requery_schedule(attempt_id) VALUES (?)",attempt);
   p.db.update("UPDATE payments SET status='PROCESSING',version=version+1 WHERE id=?",pay.get("id"));record(a,"service.trade.payment.attempt",trade,Map.of("attempt_id",attempt,"simulated",true),r);return Map.of("attempt_id",attempt.toString());});
  refresh(UUID.fromString(command.get("attempt_id").toString()),false);dueForPayment((UUID)payment(trade).get("id"));return payView(trade);
 }
 public Map<String,Object> requery(Actor a,UUID trade,String match,String key,HttpServletRequest r){owned(a,trade);channelGate();long v=version(match);commands.command(a,"service.trade.payment.requery:"+trade,key,Map.of("version",v),()->{channelGate();sameVersion(lockTrade(trade,true),v);record(a,"service.trade.payment.requery",trade,Map.of("requested",true),r);return Map.of("trade_id",trade.toString());});queryTrade(trade);return payView(trade);}
 public void queryTrade(UUID trade){channelGate();var pay=payment(trade);for(var row:p.db.queryForList("SELECT id FROM payment_attempts WHERE payment_id=? ORDER BY created_at,id",pay.get("id")))refresh((UUID)row.get("id"),false);dueForPayment((UUID)pay.get("id"));}
 public void refresh(UUID attempt,boolean close){channelGate();var seed=p.one("SELECT a.*,p.amount_fen,p.currency,p.service_trade_id FROM payment_attempts a JOIN payments p ON p.id=a.payment_id WHERE a.id=? AND p.service_trade_id IS NOT NULL",attempt);UUID trade=(UUID)seed.get("service_trade_id");
  var request=new PaymentGateway.Request(attempt,seed.get("attempt_no").toString(),seed.get("channel").toString(),number(seed.get("amount_fen")),seed.get("currency").toString());PaymentGateway.Result result;
  try{result=gateway().query(request);if(close&&result!=null&&Set.of("PENDING","NOT_FOUND","UNKNOWN").contains(result.status()))result=gateway().close(request);else if(!close&&result!=null&&"NOT_FOUND".equals(result.status())&&"CREATED".equals(seed.get("status")))result=gateway().start(request);}catch(Exception failure){result=null;}
  if(result==null||result.status()==null)result=new PaymentGateway.Result("UNKNOWN","UNAVAILABLE",null,0,request.currency());
  PaymentGateway.Result answer=result;tx.executeWithoutResult(s->{channelGate();var order=lockTrade(trade,true);var pay=p.one("SELECT * FROM payments WHERE service_trade_id=? FOR UPDATE",trade);var a=p.one("SELECT * FROM payment_attempts WHERE id=? FOR UPDATE",attempt);boolean active=Set.of("CREATED","CHANNEL_PENDING","UNKNOWN").contains(a.get("status"));
   p.db.update("UPDATE payment_requery_schedule SET next_query_at=clock_timestamp()+(?*interval '1 second'),failure_count=CASE WHEN ? THEN failure_count+1 ELSE 0 END WHERE attempt_id=?","UNKNOWN".equals(answer.status())?30:5,"UNKNOWN".equals(answer.status()),attempt);
   if(!"SUCCEEDED".equals(answer.status())){if(!active)return;String state=switch(answer.status()){case "PENDING"->"CHANNEL_PENDING";case "FAILED"->"CHANNEL_FAILED";case "CLOSED"->"CANCELLED";default->"UNKNOWN";};attemptState(attempt,state);if(Set.of("CHANNEL_FAILED","CANCELLED").contains(state)&&"PROCESSING".equals(pay.get("status")))p.db.update("UPDATE payments SET status='PENDING',version=version+1 WHERE id=?",pay.get("id"));return;}
   if(!"SIMULATED_SIMULATED_TEST".equals(answer.provider())||answer.transactionId()==null||answer.transactionId().isBlank()||answer.amountFen()<1||answer.currency()==null)throw new Failure(409,"INVALID_PROVIDER_RECEIPT");
   var prior=p.db.queryForList("SELECT * FROM payment_receipts WHERE provider=? AND channel_transaction_id=?",answer.provider(),answer.transactionId());if(!prior.isEmpty()){var existing=prior.getFirst();if(!attempt.equals(existing.get("attempt_id"))||number(existing.get("amount_fen"))!=answer.amountFen()||!answer.currency().equals(existing.get("currency")))throw new Failure(409,"RECEIPT_IDENTITY_CONFLICT");return;}
   UUID receipt=UUID.randomUUID();p.db.update("INSERT INTO payment_receipts(id,attempt_id,provider,channel_transaction_id,amount_fen,currency) VALUES (?,?,?,?,?,?)",receipt,attempt,answer.provider(),answer.transactionId(),answer.amountFen(),answer.currency());attemptState(attempt,"CHANNEL_SUCCEEDED");
   String reason="SUCCEEDED".equals(pay.get("status"))?"DUPLICATE_COLLECTION":!"AWAITING_PAYMENT".equals(order.get("order_state"))||!"HELD".equals(order.get("capacity_state"))||"CLOSED".equals(pay.get("status"))?"LATE_COLLECTION":number(pay.get("amount_fen"))!=answer.amountFen()?"AMOUNT_MISMATCH":!pay.get("currency").equals(answer.currency())?"CURRENCY_MISMATCH":null;
   if(reason!=null){UUID c=UUID.randomUUID();String refundNo="SR"+c.toString().replace("-","");p.db.update("INSERT INTO payment_cases(id,payment_id,attempt_id,receipt_id,reason_code,refund_no) VALUES (?,?,?,?,?,?)",c,pay.get("id"),attempt,receipt,reason,refundNo);refundIntent(trade,pay,receipt,c,"COMPENSATION","case:"+c,answer.amountFen(),answer.currency(),refundNo);if(active&&"PROCESSING".equals(pay.get("status")))p.db.update("UPDATE payments SET status='PENDING',version=version+1 WHERE id=?",pay.get("id"));record(null,"service.trade.payment.exception",trade,Map.of("case_id",c,"reason_code",reason),null);outbox.append("SERVICE_TRADE",trade.toString(),"ServicePaymentException",1,Map.of("trade_id",trade,"case_id",c),null);return;}
   if("PENDING".equals(pay.get("status")))p.db.update("UPDATE payments SET status='PROCESSING',version=version+1 WHERE id=?",pay.get("id"));
   p.db.update("UPDATE payments SET status='SUCCEEDED',successful_attempt_id=?,successful_receipt_id=?,paid_at=?,version=version+1 WHERE id=?",attempt,receipt,now(),pay.get("id"));
   p.db.update("UPDATE service_trade_orders SET order_state='CONFIRMED',payment_state='SUCCEEDED',capacity_state='CONFIRMED',receipt_id=?,confirmed_at=?,version=version+1 WHERE id=?",receipt,now(),trade);
   moneyEvent(trade,(UUID)pay.get("id"),receipt,null,"SERVICE_COLLECTION",answer.amountFen());record(null,"service.trade.payment.confirm",trade,Map.of("receipt_id",receipt,"amount_fen",answer.amountFen(),"simulated",true),null);outbox.append("SERVICE_TRADE",trade.toString(),"ServiceTradeConfirmed",1,Map.of("trade_id",trade,"receipt_id",receipt),null);
  });
 }
 private void attemptState(UUID attempt,String state){p.db.update("UPDATE payment_attempts SET status=?,version=version+1 WHERE id=? AND status<>?",state,attempt,state);}
 private void moneyEvent(UUID trade,UUID payment,UUID receipt,UUID refund,String type,long amount){p.db.update("INSERT INTO service_trade_money_events(id,trade_id,payment_id,receipt_id,refund_id,entry_type,amount_fen,currency,occurred_at) VALUES (?,?,?,?,?,?,?,'CNY',?)",UUID.randomUUID(),trade,payment,receipt,refund,type,amount,now());}
 private void closeActive(UUID trade){var pay=payment(trade);var active=p.db.queryForList("SELECT id FROM payment_attempts WHERE payment_id=? AND status IN "+ACTIVE+" ORDER BY id",pay.get("id"));for(var row:active)refresh((UUID)row.get("id"),true);if(p.db.queryForObject("SELECT count(*) FROM payment_attempts WHERE payment_id=? AND status IN "+ACTIVE,Integer.class,pay.get("id"))>0)throw new Failure(409,"PAYMENT_CONFIRMATION_PENDING");}
 private void noActive(UUID payment){if(p.db.queryForObject("SELECT count(*) FROM payment_attempts WHERE payment_id=? AND status IN "+ACTIVE,Integer.class,payment)>0)throw new Failure(409,"PAYMENT_CONFIRMATION_PENDING");}
 public Map<String,Object> cancel(Actor a,UUID trade,UUID store,String reason,String match,String key,HttpServletRequest r){if(store!=null)staff(a,store);var original=store==null?owned(a,trade):p.one("SELECT * FROM service_trade_orders WHERE id=? AND store_id=?",trade,store);long v=version(match);
  if(Set.of("AWAITING_PAYMENT","CONFIRMED").contains(original.get("order_state"))&&number(original.get("version"))==v)closeActive(trade);
  commands.command(a,(store==null?"service.trade.cancel:":"service.trade.merchant.cancel:")+trade,key,Map.of("version",v),()->{if(store==null)owned(a,trade);else staff(a,store);var row=lockTrade(trade,true);sameVersion(row,v);var pay=p.one("SELECT * FROM payments WHERE service_trade_id=? FOR UPDATE",trade);noActive((UUID)pay.get("id"));
   if("AWAITING_PAYMENT".equals(row.get("order_state"))){closeUnpaid(trade,pay,"CANCELLED",reason);}
   else if("CONFIRMED".equals(row.get("order_state"))){channelGate();if(!refundRulesKnown(row)||!beforeStart(row)||!"NOT_STARTED".equals(row.get("fulfillment_state"))||Boolean.TRUE.equals(p.db.queryForObject("SELECT service_trade_open_dispute(?)",Boolean.class,trade)))throw new Failure(409,"SERVICE_REFUND_REVIEW_REQUIRED");if(store==null&&!beforeCutoff(row))throw new Failure(409,"SERVICE_REFUND_REVIEW_REQUIRED");long remaining=available(row,pay);if(sum(trade,"state<>'SUCCEEDED'")>0)throw new Failure(409,"SERVICE_REFUND_ALREADY_RESERVED");if(remaining>0)refundIntent(trade,pay,(UUID)pay.get("successful_receipt_id"),null,"CANCELLATION","cancel:"+trade,remaining,"CNY",null);
    p.db.update("UPDATE service_trade_orders SET order_state='CANCELLED',capacity_state='RELEASED',closed_at=?,cancel_reason=?,version=version+1 WHERE id=?",now(),reason,trade);
   }else throw new Failure(409,"SERVICE_TRADE_ALREADY_CLOSED");record(a,store==null?"service.trade.cancel":"service.trade.merchant.cancel",trade,Map.of("reason_code",reason,"simulated",true),r);return Map.of("trade_id",trade.toString());});
  if("SUCCEEDED".equals(payment(trade).get("status")))dueForPayment((UUID)payment(trade).get("id"));return tradeView(trade);
 }
 private boolean refundRulesKnown(Map<String,Object> row){var rules=p.json.readValue(row.get("snapshot").toString(),Map.class);Object cutoff=rules.get("cancel_cutoff_minutes");return "CNY".equals(rules.get("currency"))&&"WHOLE_SLOT".equals(rules.get("billing_unit"))&&"FULL_REFUND".equals(rules.get("merchant_cancel"))&&"MANUAL_REVIEW".equals(rules.get("consumer_late_cancel"))&&"MANUAL_REVIEW".equals(rules.get("no_show"))&&cutoff instanceof Number n&&n.doubleValue()==n.longValue()&&n.longValue()>=0&&n.longValue()<=129600;}
 private boolean beforeStart(Map<String,Object> row){return clock.instant().isBefore(((Timestamp)p.one("SELECT starts_at FROM booking_slots WHERE id=?",row.get("slot_id")).get("starts_at")).toInstant());}
 private boolean beforeCutoff(Map<String,Object> row){if(!refundRulesKnown(row))return false;var rules=p.json.readValue(row.get("snapshot").toString(),Map.class);Instant start=((Timestamp)p.one("SELECT starts_at FROM booking_slots WHERE id=?",row.get("slot_id")).get("starts_at")).toInstant();return clock.instant().isBefore(start.minusSeconds(Math.multiplyExact(number(rules.get("cancel_cutoff_minutes")),60)));}
 private void closeUnpaid(UUID trade,Map<String,Object> pay,String state,String reason){if(!"PENDING".equals(pay.get("status")))throw new Failure(409,"PAYMENT_CONFIRMATION_PENDING");p.db.update("UPDATE payments SET status='CLOSED',version=version+1 WHERE id=?",pay.get("id"));p.db.update("UPDATE service_trade_orders SET order_state=?,payment_state='CLOSED',capacity_state='RELEASED',closed_at=?,cancel_reason=?,version=version+1 WHERE id=?",state,now(),reason,trade);}
 public boolean expire(UUID trade){var original=p.one("SELECT * FROM service_trade_orders WHERE id=?",trade);if(!"AWAITING_PAYMENT".equals(original.get("order_state")))return false;try{closeActive(trade);}catch(Failure blocked){if(Set.of("PAYMENT_CONFIRMATION_PENDING","SERVICE_PAYMENT_SIMULATION_DISABLED","SERVICE_SIMULATED_PROVIDER_REQUIRED","SERVICE_TRADE_SIMULATION_DISABLED","PILOT_PAUSED","RECEIPT_IDENTITY_CONFLICT","INVALID_PROVIDER_RECEIPT").contains(blocked.code)){org.slf4j.LoggerFactory.getLogger(ServiceTradeFinance.class).warn("Service expiry retained: {} {}",trade,blocked.code);return false;}throw blocked;}
  return Boolean.TRUE.equals(tx.execute(s->{var row=lockTrade(trade,true);if(!"AWAITING_PAYMENT".equals(row.get("order_state"))||number(row.get("version"))!=number(original.get("version"))||((Timestamp)row.get("hold_expires_at")).toInstant().isAfter(clock.instant()))return false;var pay=p.one("SELECT * FROM payments WHERE service_trade_id=? FOR UPDATE",trade);noActive((UUID)pay.get("id"));closeUnpaid(trade,pay,"EXPIRED","PAYMENT_WINDOW_EXPIRED");record(null,"service.trade.expire",trade,Map.of("simulated",true),null);return true;}));
 }
 private long available(Map<String,Object> row,Map<String,Object> pay){if(!"SUCCEEDED".equals(pay.get("status")))return 0;long used=p.db.queryForObject("SELECT coalesce(sum(amount_fen),0) FROM service_trade_refunds WHERE receipt_id=?",Long.class,pay.get("successful_receipt_id"));return Math.subtractExact(number(pay.get("amount_fen")),used);}
 private UUID refundIntent(UUID trade,Map<String,Object> pay,UUID receipt,UUID paymentCase,String source,String business,long amount,String currency,String fixedNo){if(amount<1)throw new Failure(409,"SERVICE_REFUND_ALREADY_RESERVED");UUID id=UUID.randomUUID();p.db.update("INSERT INTO service_trade_refunds(id,trade_id,payment_id,receipt_id,payment_case_id,business_key,refund_no,source_kind,amount_fen,currency,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,trade,pay.get("id"),receipt,paymentCase,business,fixedNo==null?"SR"+id.toString().replace("-",""):fixedNo,source,amount,currency,now());return id;}
 public List<Map<String,Object>> refunds(Actor a,UUID trade,UUID after,int size){owned(a,trade);channelGate();limit(size);return p.db.queryForList("SELECT id,trade_id,amount_fen,state,version,true AS simulated FROM service_trade_refunds WHERE trade_id=? AND source_kind<>'COMPENSATION' AND id>? ORDER BY id LIMIT ?",trade,after,size+1);}
 public Map<String,Object> assess(Actor a,UUID trade,String match,String key,HttpServletRequest r){channelGate();permission(a,Actor.Realm.ADMIN,"service.trade.refund.assess");long v=version(match);return commands.command(a,"service.trade.refund.assess:"+trade,key,Map.of("version",v),()->{channelGate();var row=lockTrade(trade,true);sameVersion(row,v);var pay=p.one("SELECT * FROM payments WHERE service_trade_id=? FOR UPDATE",trade);long remaining=available(row,pay);boolean disputed=Boolean.TRUE.equals(p.db.queryForObject("SELECT service_trade_open_dispute(?)",Boolean.class,trade));String basis=disputed?"MANUAL_REVIEW_REQUIRED":"SERVICE_UNAVAILABLE".equals(row.get("cancel_reason"))?"MERCHANT_CANCEL":beforeCutoff(row)?"BEFORE_CUTOFF":"MANUAL_REVIEW_REQUIRED";boolean eligible=!disputed&&refundRulesKnown(row)&&beforeStart(row)&&"NOT_STARTED".equals(row.get("fulfillment_state"))&&remaining>0&&!"MANUAL_REVIEW_REQUIRED".equals(basis);UUID id=UUID.randomUUID();Timestamp createdAt=now();p.db.update("INSERT INTO service_trade_refund_assessments(id,trade_id,trade_version,terms_sha256,receipt_id,proposed_refund_fen,basis_code,eligible_for_approval,created_by,created_at,expires_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,trade,v,row.get("terms_sha256"),pay.get("successful_receipt_id"),eligible?remaining:0,basis,eligible,a.principalId(),createdAt,Timestamp.from(createdAt.toInstant().plusSeconds(300)));record(a,"service.trade.refund.assess",trade,Map.of("assessment_id",id),r);return assessmentView(id);});}
 private Map<String,Object> assessmentView(UUID id){return p.view(p.one("SELECT id,trade_id,terms_sha256,proposed_refund_fen,basis_code,eligible_for_approval,expires_at,trade_version,true AS simulated FROM service_trade_refund_assessments WHERE id=?",id));}
 public Map<String,Object> decide(Actor a,UUID trade,Map<String,Object>b,String match,String key,String proof,HttpServletRequest r){channelGate();permission(a,Actor.Realm.ADMIN,"service.trade.refund.review");fields(b,"assessment_id","decision","reason_code");UUID assessment=id(b.get("assessment_id"));boolean approve="APPROVE".equals(b.get("decision"));if(!(approve&&"SNAPSHOT_RULES_APPLY".equals(b.get("reason_code"))||"REJECT".equals(b.get("decision"))&&"EVIDENCE_INSUFFICIENT".equals(b.get("reason_code"))))throw new Failure(400,"VALIDATION_ERROR");long v=version(match);
  var result=commands.command(a,"service.trade.refund.review:"+trade,key,Map.of("body",b,"version",v),()->{channelGate();var row=lockTrade(trade,true);sameVersion(row,v);var pay=p.one("SELECT * FROM payments WHERE service_trade_id=? FOR UPDATE",trade);var snap=p.one("SELECT * FROM service_trade_refund_assessments WHERE id=? AND trade_id=?",assessment,trade);if(number(snap.get("trade_version"))!=v||!row.get("terms_sha256").equals(snap.get("terms_sha256"))||!((Timestamp)snap.get("expires_at")).toInstant().isAfter(clock.instant()))throw new Failure(409,"SERVICE_REFUND_ASSESSMENT_EXPIRED");
   if(!p.db.queryForList("SELECT id FROM service_trade_refund_decisions WHERE assessment_id=?",assessment).isEmpty())throw new Failure(409,"SERVICE_REFUND_ASSESSMENT_USED");if(approve&&(Boolean.TRUE.equals(p.db.queryForObject("SELECT service_trade_open_dispute(?)",Boolean.class,trade))||!refundRulesKnown(row)||!beforeStart(row)||!"NOT_STARTED".equals(row.get("fulfillment_state"))||"BEFORE_CUTOFF".equals(snap.get("basis_code"))&&!beforeCutoff(row)||!Boolean.TRUE.equals(snap.get("eligible_for_approval"))||!Objects.equals(snap.get("receipt_id"),pay.get("successful_receipt_id"))||number(snap.get("proposed_refund_fen"))!=available(row,pay)))throw new Failure(409,"SERVICE_REFUND_REVIEW_REQUIRED");
   auth.consumeProof(a,"service.trade.refund.review",proof);UUID decision=UUID.randomUUID(),refund=approve?refundIntent(trade,pay,(UUID)pay.get("successful_receipt_id"),null,"ADMIN","assessment:"+assessment,number(snap.get("proposed_refund_fen")),"CNY",null):null;
   if(approve)bump(trade);p.db.update("INSERT INTO service_trade_refund_decisions(id,trade_id,assessment_id,decision,reason_code,refund_id,version,created_by,decided_at) VALUES (?,?,?,?,?,?,?,?,?)",decision,trade,assessment,b.get("decision"),b.get("reason_code"),refund,approve?v+1:v,a.principalId(),now());record(a,"service.trade.refund.review",trade,Map.of("decision_id",decision,"approved",approve),r);var data=new LinkedHashMap<String,Object>();data.put("id",decision);data.put("trade_id",trade);data.put("assessment_id",assessment);data.put("decision",b.get("decision"));data.put("refund_id",refund);data.put("version",approve?v+1:v);data.put("simulated",true);return data;});
  if(approve)dueForPayment((UUID)payment(trade).get("id"));return result;
 }
 public void dueForPayment(UUID payment){channelGate();for(var row:p.db.queryForList("SELECT id FROM service_trade_refunds WHERE payment_id=? AND "+DUE+" ORDER BY created_at,id",payment))driveRefund((UUID)row.get("id"));}
 public void driveRefund(UUID id){channelGate();var seed=p.one("SELECT trade_id,payment_id FROM service_trade_refunds WHERE id=?",id);var held=tx.execute(s->{lockTrade((UUID)seed.get("trade_id"),true);p.one("SELECT id FROM payments WHERE id=? FOR UPDATE",seed.get("payment_id"));var rows=p.db.queryForList("SELECT * FROM service_trade_refunds WHERE id=? AND "+DUE+" FOR UPDATE SKIP LOCKED",id);if(rows.isEmpty())return null;var current=rows.getFirst();if(number(current.get("attempt_count"))>=8){p.db.update("UPDATE service_trade_refunds SET state='NEEDS_REVIEW',version=version+1,lease_token=NULL,lease_until=NULL,last_error_code='LEASE_EXPIRED_RETRY_EXHAUSTED' WHERE id=?",id);if(current.get("payment_case_id")!=null)p.db.update("UPDATE payment_cases SET status='NEEDS_REVIEW',attempt_count=8,last_error_code='LEASE_EXPIRED_RETRY_EXHAUSTED' WHERE id=?",current.get("payment_case_id"));else bump((UUID)seed.get("trade_id"));record(null,"service.trade.refund.result",(UUID)seed.get("trade_id"),Map.of("refund_id",id,"state","NEEDS_REVIEW","attempt_count",8),null);return null;}UUID token=UUID.randomUUID();p.db.update("UPDATE service_trade_refunds SET state='PROCESSING',attempt_count=attempt_count+1,version=version+1,lease_token=?,lease_until=clock_timestamp()+(?*interval '1 millisecond'),last_error_code=NULL WHERE id=?",token,leaseMs,id);return p.one("SELECT * FROM service_trade_refunds WHERE id=?",id);});if(held==null)return;
  PaymentGateway.RefundOutcome result;try{var receipt=p.one("SELECT * FROM payment_receipts WHERE id=?",held.get("receipt_id"));var instruction=new PaymentGateway.RefundInstruction(held.get("refund_no").toString(),receipt.get("provider").toString(),receipt.get("channel_transaction_id").toString(),number(held.get("amount_fen")),held.get("currency").toString());result=gateway().queryRefund(instruction);if(result!=null&&"NOT_FOUND".equals(result.status()))result=gateway().refund(instruction);}catch(Exception failure){result=null;}
  if(result==null||result.status()==null||"NOT_FOUND".equals(result.status())||"SUCCEEDED".equals(result.status())&&(result.channelRefundNo()==null||result.channelRefundNo().isBlank()))result=new PaymentGateway.RefundOutcome("UNKNOWN",null,"PROVIDER_INVALID_OR_UNAVAILABLE");
  PaymentGateway.RefundOutcome answer=result;tx.executeWithoutResult(s->{channelGate();UUID trade=(UUID)held.get("trade_id");lockTrade(trade,true);p.one("SELECT id FROM payments WHERE id=? FOR UPDATE",held.get("payment_id"));var rows=p.db.queryForList("SELECT * FROM service_trade_refunds WHERE id=? AND state='PROCESSING' AND lease_token=? AND lease_until>clock_timestamp() FOR UPDATE",id,held.get("lease_token"));if(rows.isEmpty())return;var row=rows.getFirst();int attempts=((Number)row.get("attempt_count")).intValue();boolean success="SUCCEEDED".equals(answer.status());String state=success?"SUCCEEDED":attempts>=8?"NEEDS_REVIEW":"FAILED".equals(answer.status())?"FAILED_RETRYABLE":"UNKNOWN";
   p.db.update("UPDATE service_trade_refunds SET state=?,version=version+1,channel_refund_no=?,decided_at=?,last_error_code=?,lease_token=NULL,lease_until=NULL,next_retry_at=clock_timestamp()+(?*interval '1 second') WHERE id=?",state,success?answer.channelRefundNo():null,success?now():null,success?null:answer.errorCode(),Math.min(300,5L*(1L<<Math.min(attempts,6))),id);
   if(row.get("payment_case_id")!=null)p.db.update("UPDATE payment_cases SET status=?,attempt_count=?,last_error_code=?,next_retry_at=clock_timestamp()+interval '30 second' WHERE id=?",success?"REFUNDED":attempts>=8?"NEEDS_REVIEW":"REFUND_PENDING",attempts,success?null:answer.errorCode(),row.get("payment_case_id"));
   else if(success)moneyEvent(trade,(UUID)row.get("payment_id"),(UUID)row.get("receipt_id"),id,"SERVICE_REFUND",number(row.get("amount_fen")));
   if(row.get("payment_case_id")==null)bump(trade);record(null,"service.trade.refund.result",trade,Map.of("refund_id",id,"state",state,"attempt_count",attempts),null);outbox.append("SERVICE_TRADE",trade.toString(),"ServiceRefundResult",1,Map.of("trade_id",trade,"refund_id",id,"state",state),null);
  });
 }
 /** Called under slot/trade/payment locks by the existing action-bound administrative requery. */
 public void restartForPayment(UUID payment){channelGate();p.db.update("UPDATE service_trade_refunds SET state='FAILED_RETRYABLE',attempt_count=0,version=version+1,next_retry_at=clock_timestamp(),last_error_code='MANUAL_RETRY_REQUESTED',lease_token=NULL,lease_until=NULL WHERE payment_id=? AND state='NEEDS_REVIEW'",payment);}
 @Scheduled(fixedDelayString="${pawday.service-trade.finance-recovery-delay-ms:5000}") public void recover(){if(!recoveryEnabled)return;recoverBatch();}
 public int recoverBatch(){if(!enabled||!paymentEnabled||pilot.paused()||!(gateways.getIfAvailable() instanceof SimulatedPaymentGateway))return 0;int count=0;for(var row:p.db.queryForList("SELECT id FROM service_trade_refunds WHERE "+DUE+" ORDER BY next_retry_at,id LIMIT 50")){try{driveRefund((UUID)row.get("id"));count++;}catch(Exception failure){org.slf4j.LoggerFactory.getLogger(ServiceTradeFinance.class).warn("Service refund retained for recovery: {}",row.get("id"));}}return count;}
}
